module RAM(
    input clk, input rst_n, input write_en, input [3:0] write_addr, input [5:0] write_data, input read_en, input [3:0] read_addr, output reg [5:0] read_data
);
    parameter WIDTH = 6;
    parameter DEPTH = 8;
    reg [WIDTH-1:0] internal_RAM [DEPTH-1:0];
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (int i = 0; i < DEPTH; i = i + 1) begin
                internal_RAM[i] <= 0;
            end
        end else begin
            if (write_en) begin
                internal_RAM[write_addr] <= write_data;
            end
            if (read_en) begin
                read_data <= internal_RAM[read_addr];
            end
        end
    end
endmodule
